import { Decimal } from '../domain/shared/decimal.ts';
import { LoanApplication } from '../domain/loan/LoanApplication.ts';
import { InvalidLoanInputError } from '../domain/loan/InvalidLoanInputError.ts';

// El monto del legacy tiene signo (S9(9)V99): se admite un signo negativo opcional.
const DECIMAL_PATTERN = /^-?\d+(\.\d+)?$/;
const INTEGER_PATTERN = /^\d+$/;

/**
 * Adaptador de entrada: convierte cadenas en tipos del dominio.
 */
export class LoanInputMapper {
  toApplication(input: Record<string, string>): LoanApplication {
    return new LoanApplication(
      this.decimalField(input, 'principal').setScale(2, 'DOWN'),
      this.integerField(input, 'term_months'),
      this.integerField(input, 'credit_score'),
      this.integerField(input, 'customer_age'),
    );
  }

  private decimalField(input: Record<string, string>, name: string): Decimal {
    return Decimal.of(this.rawValue(input, name, DECIMAL_PATTERN));
  }

  private integerField(input: Record<string, string>, name: string): Decimal {
    return Decimal.of(this.rawValue(input, name, INTEGER_PATTERN));
  }

  private rawValue(input: Record<string, string>, name: string, pattern: RegExp): string {
    const value = input[name];
    if (typeof value !== 'string' || !pattern.test(value.trim())) {
      throw new InvalidLoanInputError(name);
    }
    return value.trim();
  }
}
